function topoSortKahnImpl(n, edges) {
  const adj = Array.from({length:n},()=>[]);
  const inDeg = new Array(n).fill(0);
  for (const [u,v] of edges) { adj[u].push(v); inDeg[v]++; }
  const queue = [];
  for (let v=0;v<n;v++) if(inDeg[v]===0) queue.push(v);
  const result = [];
  while (queue.length) {
    const u = queue.shift();
    result.push(u);
    for (const v of adj[u]) if(--inDeg[v]===0) queue.push(v);
  }
  return result.length===n ? result : null;
}

function hasCycleDirect(n, edges) {
  return topoSortKahnImpl(n, edges) === null;
}

