function topoSortDFSImpl(n, edges) {
  const adj = Array.from({length:n},()=>[]);
  for (const [u,v] of edges) adj[u].push(v);
  const state = new Array(n).fill(0);
  const result = [];
  let hasCycle = false;
  function dfs(u) {
    if (hasCycle) return;
    state[u] = 1;
    for (const v of adj[u]) {
      if (state[v]===1) { hasCycle=true; return; }
      if (state[v]===0) dfs(v);
    }
    state[u] = 2;
    result.push(u);
  }
  for (let v=0;v<n;v++) if(state[v]===0) dfs(v);
  return hasCycle ? null : result.reverse();
}

