function alienOrderImpl(words) {
  const adj = new Map();
  const inDeg = new Map();
  for (const w of words) for (const c of w) {
    if (!adj.has(c)) adj.set(c, new Set());
    if (!inDeg.has(c)) inDeg.set(c, 0);
  }
  for (let i=0;i<words.length-1;i++) {
    const w1=words[i],w2=words[i+1];
    const ml=Math.min(w1.length,w2.length);
    if (w1.length>w2.length && w1.slice(0,ml)===w2) return '';
    for (let j=0;j<ml;j++) {
      if (w1[j]!==w2[j]) {
        if (!adj.get(w1[j]).has(w2[j])) {
          adj.get(w1[j]).add(w2[j]);
          inDeg.set(w2[j], inDeg.get(w2[j])+1);
        }
        break;
      }
    }
  }
  const queue=[];
  for (const [c,d] of inDeg) if(d===0) queue.push(c);
  const result=[];
  while (queue.length) {
    queue.sort();
    const c=queue.shift();
    result.push(c);
    for (const next of adj.get(c)) {
      inDeg.set(next, inDeg.get(next)-1);
      if (inDeg.get(next)===0) queue.push(next);
    }
  }
  return result.length===inDeg.size ? result.join('') : '';
}

