function findItineraryImpl(tickets) {
  const adj = new Map();
  for (const [from,to] of tickets) {
    if (!adj.has(from)) adj.set(from,[]);
    adj.get(from).push(to);
  }
  for (const [_,d] of adj) { d.sort(); d.reverse(); }
  const result = [];
  function dfs(airport) {
    const dests = adj.get(airport) || [];
    while (dests.length) { const next = dests.pop(); dfs(next); }
    result.push(airport);
  }
  dfs('JFK');
  return result.reverse();
}

