function selectGraphAlgorithmImpl(props) {
  const {weighted,negEdges,kHop,incremental,ordering,eulerianPath,mst,allPairs}=props;
  if (eulerianPath) return "Hierholzer's O(E log E)";
  if (ordering) return 'Topological Sort (Kahn BFS or DFS post-order) O(V+E)';
  if (mst) return 'Kruskal O(E log E) or Prim O((V+E) log V)';
  if (incremental) return 'Union-Find O(α(n)) per query';
  if (allPairs) return 'Floyd-Warshall O(V^3)';
  if (kHop) return 'Bellman-Ford K+1 rounds O(K*E)';
  if (negEdges) return 'Bellman-Ford O(V*E)';
  if (weighted) return "Dijkstra's O((V+E) log V)";
  return 'BFS or DFS O(V+E)';
}

function findMinHeightTreesImpl(n, edges) {
  if (n === 1) return [0];
  const adj = Array.from({length:n},()=>new Set());
  for (const [u,v] of edges) { adj[u].add(v); adj[v].add(u); }
  let leaves = [];
  for (let i=0;i<n;i++) if(adj[i].size===1) leaves.push(i);
  let remaining = n;
  while (remaining > 2) {
    remaining -= leaves.length;
    const newLeaves = [];
    for (const leaf of leaves) {
      const nb = [...adj[leaf]][0];
      adj[nb].delete(leaf);
      if (adj[nb].size===1) newLeaves.push(nb);
    }
    leaves = newLeaves;
  }
  return leaves;
}
